///
/// Supported:
///   - comments (`#`)
///   - bare keys and dotted keys
///   - tables (`[table]`) and nested tables (`[a.b.c]`)
///   - string values with `\"`, `\\`, `\n`, `\t` escapes
///   - integer, boolean values
///   - arrays of those values (homogeneous)
///   - duplicate-key errors

priv suberror TomlError(String) {
  TomlError(String)
}

fn TomlError::to_string(self : TomlError) -> String {
  self.0
}

/// Parse TOML text and return a Json object.
///
/// Raises `TomlError` on malformed input or duplicate keys.
pub fn parse_toml(input : StringView) -> Json raise TomlError {
  let root: Map[String, Json] = {}
  parse_into(input, root)
  Json::object(root)
}

/// Internal value type before converting to Json.
priv enum TomlValue {
  TString(String)
  TInt(Int)
  TBool(Bool)
  TArray(Array[TomlValue])
  TTable(Map[String, TomlValue])
}

/// Convert internal TomlValue to Json.
fn to_json(val : TomlValue) -> Json {
  match val {
    TString(s) => Json::string(s)
    TInt(n) => Json::number(n.to_double(), repr=n.to_string())
    TBool(b) => Json::boolean(b)
    TArray(arr) =>
      Json::array(arr.map(fn(v) { to_json(v) }))
    TTable(map) => {
      let obj: Map[String, Json] = {}
      for (k, v) in map {
        obj[k] = to_json(v)
      }
      Json::object(obj)
    }
  }
}

/// Set a value at a dotted path within a nested table structure.
/// e.g. set_path({"a": {}}, ["a", "b", "c"], val) -> {"a": {"b": {"c": val}}}
fn set_path(
  table : Map[String, TomlValue],
  parts : ArrayView[String],
  value : TomlValue
) -> Unit raise TomlError {
  if parts.is_empty() {
    raise TomlError("empty key path")
  }
  let key = parts[0]
  if parts.length() == 1 {
    // Leaf assignment
    if table.contains(key) {
      raise TomlError("duplicate key: \{key}")
    }
    table[key] = value
    return
  }
  // Nested path - get or create subtable
  let rest = parts.view(1)
  if table.contains(key) {
    match table[key] {
      TTable(sub) => set_path(sub, rest, value)
      _ => raise TomlError("key \"\{key}\" is not a table")
    }
  } else {
    let sub: Map[String, TomlValue] = {}
    table[key] = TTable(sub)
    set_path(sub, rest, value)
  }
}

/// Parse TOML into the provided root map.
fn parse_into(input : StringView, root : Map[String, TomlValue]) -> Unit raise TomlError {
  let mut current_table = root
  let mut current_prefix: Array[String] = []
  let lines = input.split("\n")
  for line in lines {
    let trimmed = line.trim()
    // Skip blank lines and comment lines
    if trimmed.is_empty() || trimmed.has_prefix("#") {
      continue
    }
    // Skip lines that start with whitespace and are comments (already handled by trim/skip)
    // Table header: [table] or [table.subtable]
    if trimmed.has_prefix("[") {
      guard trimmed.has_suffix("]") else {
        raise TomlError("invalid table header: \{trimmed}")
      }
      let inner = trimmed
        .strip_prefix("[")
        .unwrap()
        .strip_suffix("]")
        .unwrap()
        .trim()
      if inner.is_empty() {
        current_table = root
        current_prefix = []
        continue
      }
      let parts = inner.to_owned().split(".").map(fn(v) { v.trim().to_owned() }).to_array()
      // Check for duplicate table headers
      current_prefix = parts
      current_table = root
      for part in parts.view(0, parts.length()) {
        let p = part.to_owned()
        if current_table.contains(p) {
          match current_table[p] {
            TTable(sub) => {
              current_table = sub
            }
            _ => raise TomlError("key \"\{p}\" is not a table")
          }
        } else {
          let sub: Map[String, TomlValue] = {}
          current_table[p] = TTable(sub)
          current_table = sub
        }
      }
      continue
    }
    // Key-value pair: key = value
    parse_key_value(trimmed, current_table) catch {
      err => raise TomlError("line: \{trimmed}: \{err.0}")
    }
  }
}

