  let eq_pos = line.find("=")
  guard let Some(eq) = eq_pos else {
    raise TomlError("expected key = value")
  }
  let key_part = line.sub(0, eq).trim()
  let val_part = line.sub(eq + 1).trim()
  if key_part.is_empty() {
    raise TomlError("empty key")
  }
  if val_part.is_empty() {
    raise TomlError("empty value")
  }
  // Parse key (could be dotted: a.b.c)
  let key_str = key_part.to_owned()
  let keys = key_str.split(".").map(fn(v) { v.trim().to_owned() }).to_array()
  let value = parse_value(val_part)?
  set_path(table, keys.view(0, keys.length()), value)
