fn parse_value(input : StringView) -> TomlValue raise TomlError {
  let trimmed = input.trim()
  // String
  if trimmed.has_prefix("\"") {
    guard trimmed.has_suffix("\"") && trimmed.length() >= 2 else {
      raise TomlError("unclosed string: \{trimmed}")
    }
    let inner = trimmed.sub(1, trimmed.length() - 1)
    let unescaped = unescape_string(inner)?
    return TString(unescaped)
  }
  // Array
  if trimmed.has_prefix("[") {
    return parse_array(trimmed)
  }
  // Boolean
  if trimmed == "true" {
    return TBool(true)
  }
  if trimmed == "false" {
    return TBool(false)
  }
  // Integer
  let int_val = @string.parse_int(trimmed) catch {
    _ => raise TomlError("unrecognized value: \{trimmed}")
  }
  TInt(int_val)
