/// Parse a TOML array: [1, 2, 3] or ["a", "b"]
fn parse_array(input : StringView) -> TomlValue raise TomlError {
  guard input.has_prefix("[") && input.has_suffix("]") else {
    raise TomlError("invalid array: \{input}")
  }
  let inner = input.sub(1, input.length() - 1).trim()
  if inner.is_empty() {
    return TArray([])
  }
  // Parse comma-separated elements
  let elems: Array[TomlValue] = []
  let mut remaining = inner
  while true {
    remaining = remaining.trim()
    if remaining.is_empty() {
      break
