    // Find the next element boundary
    if remaining.has_prefix("\"") {
      // String element - find closing quote considering escapes
      let close = find_string_end(remaining, 1)
      guard let Some(end) = close else {
        raise TomlError("unclosed string in array")
      }
      // end points to the closing quote
      let str_content = remaining.sub(1, end)
      let val = TString(unescape_string(str_content)?)
      elems.push(val)
      remaining = remaining.sub(end + 1)
    } else if remaining.has_prefix("[") {
      // Nested array
      let close = find_bracket_end(remaining, 0)
      guard let Some(end) = close else {
        raise TomlError("unclosed array in array")
      }
      let arr_content = remaining.sub(0, end + 1)
      let val = parse_array(arr_content)?
      elems.push(val)
      remaining = remaining.sub(end + 1)
    } else {
      // Number or boolean, find up to comma or end
      let comma_pos = remaining.find(",")
      let end = comma_pos.unwrap_or(remaining.length())
      let part = remaining.sub(0, end).trim()
      if !part.is_empty() {
        elems.push(parse_value(part)?)
      }
      remaining = if comma_pos.is_some() {
        remaining.sub(end + 1)
      } else {
        remaining.sub(end)
      }
    }
    // Skip comma
    remaining = remaining.trim()
    if remaining.has_prefix(",") {
      remaining = remaining.sub(1)
    }
  }
  TArray(elems)
}

/// Find the closing double-quote in a string starting at `start()` in `input`,
/// respecting backslash escapes. Returns the index of the closing `"`.
fn find_string_end(input : StringView, start : Int) -> Int? {
  let mut i = start
  while i < input.length() {
    let c = input[i]
    if c == 34 /* " */ {
      return Some(i)
    }
    if c == 92 /* \ */ {
      // Skip escaped character
      i += 2
    } else {
      i += 1
    }
  }
  None
}

/// Find the matching `]` for an array starting at `start` in `input`.
fn find_bracket_end(input : StringView, start : Int) -> Int? {
  let mut depth = 0
  let mut i = start
  while i < input.length() {
    let c = input[i]
    if c == 91 /* [ */ {
      depth += 1
    } else if c == 93 /* ] */ {
      depth -= 1
      if depth == 0 {
        return Some(i)
      }
    } else if c == 34 /* " */ {
      // Skip string content
      let close = find_string_end(input, i + 1)
      guard let Some(ci) = close else {
        return None
      }
      i = ci
    }
    i += 1
  }
  None
}

/// Unescape a TOML string: \" \\ \n \t
fn unescape_string(input : StringView) -> String raise TomlError {
  let mut result = StringBuilder::new()
  let mut i = 0
  while i < input.length() {
    let c = input[i]
    if c == 92 /* \ */ {
      if i + 1 >= input.length() {
        raise TomlError("trailing backslash")
      }
      let next = input[i + 1]
      if next == 34 /* " */ {
        result.write_char('"')
        i += 2
      } else if next == 92 /* \ */ {
        result.write_char('\\')
        i += 2
      } else if next == 110 /* n */ {
