      Some(c) => {
        if c == '[' {
          depth += 1
        } else if c == ']' {
          depth -= 1
          if depth == 0 {
            return Some(i)
          }
        } else if c == '"' {
          match find_string_end(input, i + 1) {
            None => return None
            Some(ci) => {
              i = ci
            }
          }
        }
        i += 1
      }
    }
  }
  None
}

/// Unescape a TOML string: double-quote, backslash, newline, tab.
fn unescape_string(input : StringView) -> String raise TomlError {
  let result = StringBuilder::new()
  let mut i = 0
  while i < input.length() {
    match input.get_char(i) {
      None => raise TomlError("invalid UTF in string")
      Some(c) => {
        if c == '\\' {
          if i + 1 >= input.length() {
            raise TomlError("trailing backslash")
          }
          match input.get_char(i + 1) {
            None => raise TomlError("invalid UTF after backslash")
            Some(next) => {
              if next == '"' {
                result.write_char('"')
                i += 2
              } else if next == '\\' {
                result.write_char('\\')
                i += 2
              } else if next == 'n' {
                result.write_char('\n')
                i += 2
              } else if next == 't' {
                result.write_char('\t')
                i += 2
              } else {
                raise TomlError("invalid escape: \\\{next.to_string()}")
              }
            }
          }
        } else {
          result.write_char(c)
          i += 1
        }
      }
    }
  }
  result.to_string()
}
